/* 50 SALGADOS E LANCHES SEM GLÚTEN. Formato ingrediente: "quantidade|nome". Usa a função R de content/paes.js. Lotes adicionados em sequência (veja PROGRESS.md). */
const RS=(num,...a)=>({...R(num,...a),id:"salgados"+num});
const RSC=(cook,num,...a)=>({...RS(num,...a),cook});
window.SALGADOS=[
RS(1,"Empadinhas de frango","Empadas e tortinhas","Empadinhas de massa amanteigada que se desmancha na boca, com recheio cremoso de frango e tomate.","12 empadinhas (forminhas de 6 cm de diâmetro)",40,30,"180 °C",
["180 g (1 e 1/5 de xícara)|farinha de arroz branca","60 g (1/2 xícara)|amido de milho","120 g|manteiga gelada, em cubos","1 unidade|ovo","1 unidade|gema, só para a massa","3 g (1/2 colher de chá)|sal","1 a 3 colheres de sopa|água gelada","300 g|peito de frango cozido e desfiado","1/2 unidade|cebola pequena picada","1 unidade|tomate sem pele e sem sementes, picado","1 dente|alho amassado","1 colher de sopa|azeite","1 colher de sopa (8 g)|amido de milho, para o recheio","120 ml (1/2 xícara)|água do cozimento do frango","2 colheres de sopa|salsinha picada","1 unidade|gema, para pincelar"],
["Prepare a massa: numa tigela, misture a farinha de arroz, o amido de milho e o sal. Junte a manteiga gelada e esfarele com as pontas dos dedos até obter uma farofa grossa, com pedacinhos do tamanho de ervilhas.","Adicione o ovo e a gema e misture. Se a massa estiver seca e não se juntar, acrescente a água gelada, uma colher por vez. O ponto certo é uma massa macia que se junta sem grudar nas mãos e racha um pouco nas bordas se for esticada.","Embrulhe em filme plástico e leve à geladeira por 30 minutos. Massa fria é mais fácil de modelar.","Faça o recheio: numa panela, aqueça o azeite e refogue a cebola por 3 minutos, até ficar translúcida. Junte o alho por 30 segundos, o tomate e cozinhe por 3 minutos.","Dissolva o amido de milho na água do cozimento do frango, junte à panela com o frango desfiado e mexa em fogo baixo por 3 a 4 minutos, até formar um creme espesso que não escorre da colher. Acerte o sal, junte a salsinha e deixe esfriar por completo.","Preaqueça o forno a 180 °C. Separe cerca de 2/3 da massa e divida em 12 bolinhas. Forre o fundo e as laterais das forminhas, apertando com os dedos até a massa ficar com 3 a 4 mm de espessura.","Distribua o recheio frio. Abra o restante da massa entre dois plásticos, corte 12 discos do tamanho das forminhas e cubra as empadinhas, apertando as bordas. Pincele com a gema e fure o centro com um garfo.","Asse por 28 a 30 minutos. Estão prontas quando a tampa estiver dourada e as bordas ligeiramente coradas. Espere amornar por 10 minutos antes de desenformar, pois a massa é frágil quente."],
["O recheio deve estar frio ao montar, senão a manteiga da massa derrete e a empada fica pesada.","Se a massa quebrar ao forrar as forminhas, remende com os dedos: ela é facilmente consertada.","Confira no rótulo o amido de milho, a manteiga e a farinha de arroz. Evite forminhas e tábuas que tenham sido usadas com farinha de trigo."],
"Até 3 dias na geladeira, em recipiente fechado, pois o recheio é perecível. Congele já assadas por até 2 meses e reaqueça no forno a 180 °C por 10 minutos.","empada empadinha frango festa lanche massa amanteigada forminha"),
RS(2,"Empadão de palmito com massa de batata","Empadas e tortinhas","Empadão macio, com massa de batata e recheio cremoso de palmito, bom para servir em fatias com salada.","1 empadão de 22 cm de diâmetro (8 fatias)",50,40,"190 °C",
["400 g|batatas cozidas e espremidas, ainda mornas","120 g (1 xícara)|fécula de batata","60 g|manteiga em temperatura ambiente","1 unidade|ovo","5 g (1 colher de chá)|sal","1 colher de sopa|manteiga, para untar","1 colher de sopa|fécula de batata, para polvilhar","1 vidro (300 g de palmito escorrido)|palmito pupunha ou açaí em conserva, em rodelas","1/2 unidade|cebola picada","1 dente|alho amassado","2 colheres de sopa|azeite","240 ml (1 xícara)|leite","2 colheres de sopa (16 g)|amido de milho","60 g|queijo mussarela em cubinhos","2 colheres de sopa|salsinha picada","1 unidade|gema, para pincelar"],
["Prepare a massa: misture a batata espremida, a fécula, a manteiga, o ovo e o sal até formar uma massa macia e lisa. Ela deve soltar das mãos, mas ficar levemente grudenta. Se grudar demais, junte 1 colher de sopa de fécula por vez.","Embrulhe em filme plástico e deixe na geladeira por 20 minutos.","Faça o recheio: aqueça o azeite e refogue a cebola por 3 minutos. Junte o alho, o palmito e refogue por 3 minutos. Dissolva o amido no leite frio, despeje na panela e mexa em fogo baixo por 4 a 5 minutos, até virar um creme espesso. Acerte o sal, desligue e misture a salsinha. Deixe esfriar e junte a mussarela.","Preaqueça o forno a 190 °C. Unte com manteiga e polvilhe com fécula uma forma de 22 cm de fundo removível.","Divida a massa em duas partes, uma um pouco maior. Abra a parte maior entre dois plásticos polvilhados com fécula, com 5 mm de espessura, e forre o fundo e as laterais da forma.","Espalhe o recheio frio. Abra a outra parte e cubra, apertando as bordas com um garfo. Pincele com a gema e fure o topo em 3 pontos para sair o vapor.","Asse por 35 a 40 minutos, até a superfície ficar dourada. Espere 15 minutos antes de desenformar e cortar, para o recheio assentar."],
["Use batatas cozidas sem excesso de água: escorra bem e deixe secar no vapor da panela por 2 minutos antes de espremer.","Não bata a massa no processador, para a batata não ficar elástica e pegajosa.","Confira no rótulo o palmito em conserva, o amido de milho e a mussarela ralada pronta, que pode conter antiaglomerantes com glúten. Prefira queijo em peça."],
"Até 3 dias na geladeira em recipiente fechado. Congela em fatias por até 2 meses. Reaqueça no forno a 180 °C por 15 minutos.","empadão palmito batata torta festa almoço queijo"),
RS(3,"Torta de liquidificador de frango","Tortas","Torta clássica de liquidificador, com massa macia e recheio de frango temperado com milho e requeijão.","1 torta em forma de 24 x 34 cm (12 pedaços)",25,40,"180 °C",
["150 g (1 xícara)|farinha de arroz branca","100 g (2/3 de xícara)|polvilho doce","3 unidades|ovos","240 ml (1 xícara)|leite","100 ml|óleo de girassol","12 g (1 colher de sopa rasa)|fermento químico em pó","5 g (1 colher de chá)|sal","30 g (1/4 de xícara)|queijo parmesão ralado","400 g|peito de frango cozido e desfiado","1/2 unidade|cebola picada","1 dente|alho amassado","1 colher de sopa|azeite","140 g (1 lata, escorrida)|milho verde","150 g (3/4 de xícara)|requeijão cremoso","2 colheres de sopa|salsinha picada","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar"],
["Prepare o recheio: refogue a cebola no azeite por 3 minutos, junte o alho, o frango, o milho, sal a gosto e cozinhe por 3 minutos. Desligue, misture o requeijão e a salsinha. Deixe amornar.","Preaqueça o forno a 180 °C. Unte uma forma de 24 x 34 cm com a manteiga e polvilhe com farinha de arroz.","No liquidificador, bata os ovos, o leite, o óleo e o sal por 1 minuto. Junte a farinha de arroz, o polvilho doce e o parmesão e bata por mais 1 minuto.","Por último, acrescente o fermento e bata por apenas 10 segundos, só para misturar. A massa fica fluida, um pouco mais grossa que massa de panqueca.","Despeje metade da massa na forma. Espalhe o recheio sem chegar às bordas e cubra com o restante da massa, com cuidado para não misturar.","Asse por 35 a 40 minutos. Está pronta quando o topo estiver bem dourado e um palito inserido na massa sair limpo, sem massa crua. Espere 10 minutos antes de cortar."],
["O recheio precisa estar morno ou frio para não cozinhar a massa de baixo antes do forno.","Se quiser a massa mais firme, reduza o leite para 220 ml.","Confira no rótulo o requeijão, o milho, o parmesão ralado e o fermento. Prefira queijo ralado na hora, sem aditivos."],
"Até 3 dias na geladeira, bem coberta. Congela em pedaços por até 2 meses. Reaqueça no forno ou no micro-ondas até ficar quente por inteiro.","torta liquidificador frango milho requeijão festa lanche"),
RS(4,"Torta de legumes com massa de grão-de-bico","Tortas","Torta rústica e saborosa, com massa feita de farinha de grão-de-bico e recheio de legumes e queijo.","1 torta em forma de 22 cm (8 pedaços)",25,40,"180 °C",
["120 g (1 xícara)|farinha de grão-de-bico","60 g (1/2 xícara)|fécula de batata","3 unidades|ovos","240 ml (1 xícara)|leite","80 ml|azeite","10 g (2 colheres de chá rasas)|fermento químico em pó","5 g (1 colher de chá)|sal","2 unidades|cenouras raladas","1 unidade|abobrinha pequena ralada","1 xícara (cerca de 90 g)|brócolis em floretes pequenos","1/2 unidade|cebola picada","1 dente|alho amassado","100 g|queijo mussarela em cubinhos","1 colher de sopa|azeite, para refogar","1 colher de sopa|azeite, para untar a forma"],
["Preaqueça o forno a 180 °C e unte com azeite uma forma redonda de 22 cm.","Refogue a cebola no azeite por 3 minutos, junte o alho, a cenoura e cozinhe por 3 minutos. Acrescente a abobrinha, o brócolis, sal a gosto e cozinhe por mais 3 minutos, mexendo. Desligue e deixe amornar.","No liquidificador, bata os ovos, o leite, o azeite e o sal por 1 minuto. Junte a farinha de grão-de-bico e a fécula e bata por 1 minuto.","Adicione o fermento e bata por apenas 10 segundos. A massa deve ficar levemente espessa, escorrendo da colher.","Misture os legumes à massa com uma colher, junte a mussarela e despeje na forma.","Asse por 35 a 40 minutos. Está pronta quando a superfície estiver dourada, firme ao toque e um palito sair limpo do centro. Espere 10 minutos antes de desenformar."],
["A farinha de grão-de-bico tem sabor marcante. Se quiser suavizá-lo, junte 1 colher de chá de orégano à massa.","Escorra bem os legumes ralados, apertando com as mãos, para a torta não ficar encharcada.","Confira no rótulo a farinha de grão-de-bico, que pode ser embalada em locais que processam trigo. Prefira marcas que declarem “não contém glúten”."],
"Até 3 dias na geladeira em recipiente fechado. Congela em fatias por até 2 meses.","torta legumes grão-de-bico vegetariana brócolis cenoura abobrinha lanche"),
RS(5,"Quiche de alho-poró e queijo","Tortas","Quiche de massa amanteigada com recheio cremoso de ovos, alho-poró e queijo. Boa para o almoço ou para o lanche.","1 quiche de 22 cm (8 fatias)",45,40,"180 °C",
["150 g (1 xícara)|farinha de arroz branca","50 g (cerca de 1/3 de xícara)|fécula de batata","100 g|manteiga gelada em cubos","30 g (1/4 de xícara)|queijo parmesão ralado","1 unidade|ovo","3 g (1/2 colher de chá)|sal","1 a 2 colheres de sopa|água gelada","2 unidades|alhos-porós (só a parte branca e verde-clara), em rodelas finas","1 colher de sopa|manteiga","3 unidades|ovos","200 ml|creme de leite fresco","100 ml|leite","100 g|queijo gruyère ou queijo prato ralado","1 pitada|noz-moscada","sal e pimenta-do-reino a gosto|temperos"],
["Prepare a massa: misture a farinha, a fécula, o parmesão e o sal. Esfarele a manteiga até virar uma farofa. Junte o ovo e, se preciso, a água gelada, até a massa se juntar. Embrulhe e leve à geladeira por 30 minutos.","Preaqueça o forno a 180 °C. Abra a massa entre dois plásticos, com 4 mm de espessura, e forre uma forma de 22 cm de fundo removível, subindo 3 cm nas laterais. Fure o fundo com um garfo e leve ao congelador por 10 minutos.","Pré-asse a massa por 15 minutos, coberta com papel-manteiga e feijão cru como peso. Retire o peso e asse por mais 5 minutos, até secar.","Enquanto isso, refogue o alho-poró na manteiga com uma pitada de sal por 8 minutos, em fogo baixo, até ficar macio e sem soltar água. Deixe amornar.","Bata os ovos com o creme de leite, o leite, a noz-moscada, sal e pimenta, só até misturar.","Espalhe o alho-poró e metade do queijo sobre a massa, despeje o creme de ovos e cubra com o queijo restante.","Asse por 25 a 30 minutos, até o recheio firmar e dourar. Ao balançar de leve a forma, o centro deve tremer apenas um pouco. Espere 15 minutos antes de cortar."],
["Pré-assar a massa evita que o fundo fique úmido.","Se a massa rachar depois do pré-assamento, tape os buracos com uma tirinha de massa crua antes de rechear.","Confira no rótulo o creme de leite, o queijo ralado e a fécula. Não use temperos prontos sem checar o rótulo."],
"Até 3 dias na geladeira, em recipiente fechado. Pode ser congelada por até 1 mês. Sirva morna ou em temperatura ambiente por no máximo 2 horas.","quiche alho-poró queijo torta massa amanteigada ovos almoço"),
RS(6,"Torta de atum e milho com massa de arroz","Tortas","Torta simples, com massa crocante de arroz cozido e recheio cremoso de atum, milho e queijo.","1 torta de 24 cm (8 pedaços)",30,35,"200 °C",
["400 g (2 xícaras)|arroz branco cozido e frio","2 unidades|ovos","60 g (1/2 xícara)|queijo mussarela ralado","1 colher de sopa|azeite","1 colher de chá|orégano","2 latas (170 g cada, escorridas)|atum em conserva","140 g (1 lata, escorrida)|milho verde","1/2 unidade|cebola picada","1 unidade|tomate sem sementes, picado","1 colher de sopa|azeite, para refogar","150 g (3/4 de xícara)|requeijão cremoso","60 g|queijo mussarela em fatias","1 colher de sopa|salsinha picada"],
["Preaqueça o forno a 200 °C. Misture o arroz, os ovos, a mussarela ralada, o azeite, o orégano e uma pitada de sal. A mistura deve ficar úmida e grudar ao ser apertada com a colher.","Forre o fundo e as laterais de uma forma de 24 cm untada, pressionando bem com as costas de uma colher úmida, com cerca de 7 mm de espessura. Asse por 15 minutos, até firmar e dourar de leve nas bordas.","Faça o recheio: refogue a cebola no azeite por 3 minutos, junte o tomate e cozinhe 2 minutos. Acrescente o atum, o milho e a salsinha. Cozinhe por 3 minutos, desligue e misture o requeijão. Acerte o sal.","Espalhe o recheio sobre a massa pré-assada e cubra com as fatias de mussarela.","Asse por mais 15 a 20 minutos, até o queijo derreter e dourar. Espere 10 minutos antes de cortar."],
["Use arroz do dia anterior, mais seco, para a massa firmar melhor.","Escorra bem o atum e o milho para o recheio não soltar água.","Confira no rótulo o atum (alguns têm molho ou caldos com glúten), o milho em lata e o requeijão. Prefira atum ao natural ou em óleo."],
"Até 2 dias na geladeira, em recipiente fechado, por conter peixe. Reaqueça até ficar bem quente. Não é indicado congelar.","torta atum milho arroz massa fácil econômica peixe lanche"),
RS(7,"Torta de espinafre e ricota com massa de polvilho","Tortas","Torta com massa de polvilho que fica crocante por fora e macia por dentro, recheada com espinafre e ricota.","1 torta de 24 cm (8 pedaços)",40,40,"200 °C",
["250 g (2 e 1/2 xícaras)|polvilho azedo","100 ml|leite","100 ml|óleo de girassol","1 unidade|ovo","40 g (1/3 de xícara)|queijo parmesão ralado","3 g (1/2 colher de chá)|sal","1 colher de sopa|azeite, para untar a forma","1 maço (cerca de 300 g)|espinafre lavado, sem os talos","250 g|ricota fresca amassada","1/2 unidade|cebola picada","1 dente|alho amassado","1 colher de sopa|azeite","2 unidades|ovos","1 pitada|noz-moscada"],
["Prepare a massa: leve o leite, o óleo e o sal ao fogo até ferver. Despeje sobre o polvilho azedo numa tigela e misture com uma colher até absorver. Deixe amornar por 10 minutos.","Junte o ovo e o parmesão e amasse até obter uma massa lisa e macia, que não gruda nas mãos. Se estiver seca, acrescente 1 colher de sopa de leite.","Preaqueça o forno a 200 °C. Unte uma forma de 24 cm. Com as mãos untadas, pressione a massa no fundo e nas laterais, com 5 mm de espessura. Fure o fundo com um garfo e pré-asse por 12 minutos.","Faça o recheio: refogue a cebola no azeite por 3 minutos, junte o alho e o espinafre e cozinhe por 3 minutos, até murchar. Escorra bem, apertando com uma colher, e pique.","Misture o espinafre, a ricota, os ovos, a noz-moscada, sal e pimenta a gosto.","Despeje o recheio sobre a massa pré-assada e asse por 20 a 25 minutos, até o recheio firmar e a borda dourar. Espere 10 minutos antes de desenformar."],
["Escorra o espinafre com cuidado: a água em excesso deixa o recheio mole.","A massa de polvilho fica melhor logo depois de pronta. Não deixe descansar por muito tempo.","Confira no rótulo o polvilho azedo, a ricota e o parmesão ralado. Prefira queijos em peça."],
"Até 3 dias na geladeira, em recipiente fechado. Reaqueça no forno para recuperar a crocância da massa.","torta espinafre ricota polvilho azedo vegetariana lanche almoço"),
RS(8,"Torta de purê com carne moída","Tortas","Torta de camadas, sem massa de farinha: purê de batata cremoso sobre carne moída bem temperada, gratinada com queijo.","1 travessa de 22 x 30 cm (8 porções)",40,25,"200 °C",
["1 kg|batatas","60 g|manteiga","120 ml|leite morno","500 g|carne moída (patinho)","1 unidade|cebola picada","2 dentes|alho amassados","2 colheres de sopa|azeite","2 colheres de sopa|extrato de tomate","1 unidade|tomate picado","100 g|ervilha congelada","1 colher de sopa|salsinha picada","100 g|queijo mussarela ralado","sal, pimenta-do-reino e noz-moscada a gosto|temperos"],
["Cozinhe as batatas descascadas em água com sal por 20 minutos, até ficarem bem macias ao garfo. Escorra e amasse ainda quentes com a manteiga e o leite morno, até formar um purê liso. Tempere com sal e noz-moscada.","Refogue a cebola no azeite por 4 minutos. Junte o alho e a carne moída e mexa em fogo alto por 8 minutos, desmanchando os grumos, até secar e dourar.","Acrescente o extrato de tomate, o tomate picado e a ervilha. Cozinhe por 6 minutos em fogo médio, até secar o molho. Junte a salsinha e acerte o sal e a pimenta.","Preaqueça o forno a 200 °C. Espalhe a carne numa travessa, cubra com o purê e alise com um garfo, formando linhas.","Polvilhe com a mussarela e asse por 20 a 25 minutos, até gratinar e dourar nas pontas. Espere 10 minutos antes de servir."],
["A carne precisa ficar seca antes de ir à travessa; carne molhada deixa o purê encharcado.","Passe as batatas quentes no espremedor. Batedeira ou liquidificador deixam o purê pegajoso.","Confira no rótulo o extrato de tomate, a ervilha e a mussarela ralada. Evite caldos em cubo, que podem conter glúten."],
"Até 3 dias na geladeira, em recipiente fechado. Congela por até 2 meses. Reaqueça até ficar bem quente.","torta purê batata carne moída gratinada escondidinho almoço jantar"),
RS(9,"Tortinhas de queijo com massa de mandioca","Empadas e tortinhas","Tortinhas macias de massa de mandioca, recheadas com queijo e ervas. Boas para festas e lanches.","16 tortinhas (forminhas de 6 cm)",40,25,"200 °C",
["300 g|mandioca cozida e espremida, ainda morna","50 g (1/3 de xícara)|polvilho doce","40 g|manteiga","1 unidade|ovo","3 g (1/2 colher de chá)|sal","200 g|queijo minas padrão em cubinhos","100 g|requeijão cremoso","2 unidades|ovos","60 ml|leite","1 colher de sopa|cebolinha picada","1 colher de chá|orégano","1 colher de sopa|manteiga, para untar as forminhas"],
["Misture a mandioca espremida com a manteiga, o polvilho, o ovo e o sal. Amasse até formar uma massa macia e homogênea, sem fios da mandioca. Se grudar demais, junte 1 colher de sopa de polvilho.","Preaqueça o forno a 200 °C e unte 16 forminhas. Forre com a massa, apertando com os dedos úmidos, com 4 mm de espessura.","Prepare o recheio: misture o queijo minas, o requeijão, os ovos, o leite, a cebolinha e o orégano. Ajuste o sal só se o queijo for pouco salgado.","Encha cada forminha até 3/4 da altura. Asse por 22 a 25 minutos, até a massa dourar e o recheio estar firme e levemente dourado.","Espere 10 minutos antes de desenformar com cuidado, passando a ponta de uma faca nas laterais."],
["Retire os fios grossos da mandioca antes de cozinhar, para a massa ficar lisa.","Use mandioca cozida e escorrida, sem água sobrando, ou a massa fica mole.","Confira no rótulo o queijo minas, o requeijão e o polvilho doce."],
"Até 3 dias na geladeira, em recipiente fechado. Reaqueça no forno a 180 °C por 10 minutos. Congela por até 1 mês.","tortinha queijo mandioca festa lanche forminha minas"),
RS(10,"Torta de abobrinha e ricota sem massa","Tortas","Torta leve de abobrinha ralada, ricota e ovos, assada sem massa de farinha, para o almoço ou o jantar.","1 torta de 22 cm (8 fatias)",20,40,"180 °C",
["500 g (3 unidades médias)|abobrinhas raladas","5 g (1 colher de chá)|sal, para as abobrinhas","250 g|ricota fresca amassada","4 unidades|ovos","60 g (1/2 xícara)|fécula de batata","50 g|queijo parmesão ralado","1/2 unidade|cebola ralada","2 colheres de sopa|hortelã ou salsinha picada","10 g (2 colheres de chá rasas)|fermento químico em pó","1 colher de sopa|azeite, para untar a forma","pimenta-do-reino a gosto|tempero"],
["Misture a abobrinha ralada com o sal e deixe por 10 minutos. Aperte com as mãos ou num pano limpo, para tirar a maior parte da água.","Preaqueça o forno a 180 °C e unte uma forma de 22 cm com azeite.","Numa tigela, misture a abobrinha, a ricota, os ovos, a cebola, a hortelã ou a salsinha, o parmesão e a pimenta.","Junte a fécula e o fermento e mexa só até incorporar. A mistura deve ficar espessa e úmida.","Despeje na forma, alise o topo e asse por 35 a 40 minutos, até dourar e firmar. O centro deve estar firme ao toque e um palito sair limpo. Espere 10 minutos antes de cortar."],
["Quanto mais água sair da abobrinha, mais firme fica a torta.","Se quiser mais sabor, junte 1 colher de chá de casca de limão ralada, sem a parte branca.","Confira no rótulo a ricota, o parmesão ralado e a fécula."],
"Até 3 dias na geladeira, em recipiente fechado. Congela em fatias por até 2 meses.","torta abobrinha ricota sem massa leve vegetariana jantar almoço"),
RS(11,"Esfiha aberta de carne com massa de polvilho","Salgados assados","Esfihas abertas de massa macia e levemente crocante nas bordas, com recheio suculento de carne moída e tomate.","16 esfihas médias",40,20,"200 °C",
["250 g (2 e 1/2 xícaras)|polvilho azedo","100 ml|leite","100 ml|óleo de girassol","1 unidade|ovo","3 g (1/2 colher de chá)|sal","400 g|carne moída (patinho)","1 unidade|cebola ralada","2 unidades|tomates sem pele e sem sementes, picados","2 dentes|alho amassados","1 colher de sopa|azeite","1 colher de sopa|suco de limão","1 colher de chá|hortelã seca ou salsinha picada","1 colher de sopa|azeite, para untar a assadeira"],
["Faça o recheio: refogue a cebola e o alho no azeite por 3 minutos. Junte a carne e mexa em fogo alto por 6 minutos, até dourar. Acrescente o tomate, sal e pimenta e cozinhe por 5 minutos, até secar totalmente. Desligue, junte o limão e a hortelã e deixe esfriar.","Prepare a massa: ferva o leite, o óleo e o sal e despeje sobre o polvilho. Mexa até absorver e deixe amornar por 10 minutos. Junte o ovo e amasse até ficar lisa e macia, sem grudar nas mãos.","Preaqueça o forno a 200 °C e unte uma assadeira grande.","Com as mãos untadas, faça 16 bolinhas de cerca de 30 g, achate-as em discos de 8 cm e belisque as bordas para formar uma pequena parede.","Distribua 1 colher de sopa cheia de recheio em cada disco, sem encostar nas bordas.","Asse por 18 a 20 minutos, até as bordas dourarem e a massa ficar firme ao toque. Sirva morna."],
["O recheio precisa estar bem seco e frio. Recheio úmido amolece a massa e faz a esfiha abrir.","A massa de polvilho escaldada seca rápido. Trabalhe com ela coberta com um pano úmido.","Confira no rótulo o polvilho azedo e a carne moída, se for industrializada. Evite temperos prontos sem checar o rótulo."],
"Até 3 dias na geladeira, em recipiente fechado. Congele assadas por até 2 meses e reaqueça no forno a 180 °C por 10 minutos.","esfiha aberta carne polvilho festa lanche assado árabe"),
RS(12,"Enroladinho de salsicha com massa de batata","Salgados assados","Enroladinhos macios de massa de batata, ótimos para festas infantis e lanches.","16 enroladinhos",35,25,"200 °C",
["400 g|batatas cozidas e espremidas, ainda mornas","120 g (1 xícara)|fécula de batata","40 g|manteiga","1 unidade|ovo","5 g (1 colher de chá)|sal","8 unidades|salsichas de boa qualidade, cortadas ao meio","1 unidade|gema, para pincelar","1 colher de sopa|sementes de gergelim, para polvilhar","1 colher de sopa|fécula, para a bancada"],
["Preaqueça o forno a 200 °C e forre uma assadeira com papel-manteiga.","Misture a batata, a fécula, a manteiga, o ovo e o sal até formar uma massa macia que solta das mãos. Se grudar muito, junte fécula, 1 colher de sopa por vez.","Abra a massa sobre a bancada polvilhada com fécula, com 4 mm de espessura, e corte 16 tiras de 4 cm de largura.","Enrole cada tira em espiral em volta de meia salsicha, apertando as pontas.","Disponha na assadeira, pincele com a gema e polvilhe o gergelim.","Asse por 22 a 25 minutos, até a massa dourar por igual. Espere 5 minutos antes de servir."],
["A massa de batata fica melhor com batata seca. Deixe-a perder vapor depois de cozida.","Salsichas e embutidos costumam conter glúten ou traços. Escolha só marcas que declarem “não contém glúten” no rótulo.","Se a massa rachar ao enrolar, passe uma gota de água na emenda e aperte."],
"Até 3 dias na geladeira, em recipiente fechado. Congela já assado por até 2 meses.","enroladinho salsicha batata festa infantil lanche assado"),
RS(13,"Enroladinho de queijo e presunto com massa de iogurte","Salgados assados","Massa leve de iogurte e polvilho, enrolada com presunto e queijo derretido por dentro.","12 enroladinhos",30,25,"190 °C",
["170 g (1 pote)|iogurte natural integral","80 ml|óleo de girassol","1 unidade|ovo","180 g (1 e 1/2 xícara)|polvilho doce","120 g (cerca de 3/4 de xícara)|farinha de arroz branca","10 g (2 colheres de chá rasas)|fermento químico em pó","3 g (1/2 colher de chá)|sal","150 g|presunto fatiado","150 g|queijo mussarela fatiado","1 unidade|gema, para pincelar","2 colheres de sopa|farinha de arroz, para a bancada"],
["Preaqueça o forno a 190 °C e forre uma assadeira com papel-manteiga.","Misture o iogurte, o óleo e o ovo. Junte o polvilho, a farinha de arroz, o fermento e o sal e mexa até formar uma massa macia, que se mantenha unida.","Abra a massa sobre a bancada polvilhada, com 4 mm de espessura, num retângulo de 24 x 36 cm. Corte em 12 triângulos.","Coloque uma fatia pequena de presunto e de queijo na base de cada triângulo e enrole em direção à ponta.","Disponha na assadeira com a ponta para baixo, pincele com a gema e asse por 22 a 25 minutos, até dourar. Espere 5 minutos antes de servir."],
["Não coloque muito recheio, ou o queijo escapa durante o assado.","A massa fica um pouco pegajosa. Use pouca farinha extra para não endurecer.","Confira no rótulo o presunto, o queijo fatiado, o iogurte e o polvilho."],
"Até 3 dias na geladeira, em recipiente fechado. Congela por até 2 meses.","enroladinho queijo presunto iogurte festa lanche assado"),
RS(14,"Pastel assado de queijo com massa de arroz","Salgados assados","Pastéis de massa fina e firme, assados em vez de fritos, com recheio de queijo e orégano.","12 pastéis",40,25,"200 °C",
["200 g (1 e 1/3 de xícara)|farinha de arroz branca","60 g (1/2 xícara)|fécula de batata","60 g|manteiga","1 unidade|ovo","120 ml|água morna","5 g (1 colher de chá)|sal","200 g|queijo mussarela em cubinhos","1 colher de chá|orégano","1 unidade|gema, para pincelar","2 colheres de sopa|fécula, para a bancada"],
["Misture a farinha de arroz, a fécula e o sal. Junte a manteiga em temperatura ambiente, o ovo e a água morna e amasse até formar uma massa lisa, elástica e que não grude nas mãos. Se estiver seca, junte 1 colher de sopa de água.","Cubra e deixe a massa descansar por 15 minutos.","Preaqueça o forno a 200 °C e forre uma assadeira com papel-manteiga.","Abra a massa sobre a bancada polvilhada com fécula, com 2 mm de espessura. Corte discos de 10 cm. Reúna as sobras e abra de novo.","Coloque queijo e orégano no centro de cada disco, passe um pouco de água na borda, dobre ao meio e feche com um garfo.","Pincele com a gema, fure o topo e asse por 22 a 25 minutos, até dourar. Espere 5 minutos antes de comer."],
["Se a massa rachar ao dobrar, deixe-a descansar mais um pouco e trabalhe com as mãos levemente úmidas.","O queijo não pode encostar na borda, para o pastel não abrir.","Confira no rótulo a mussarela e a fécula. Evite queijos ralados prontos."],
"Até 2 dias na geladeira, em recipiente fechado. Reaqueça no forno para recuperar a crocância. Congela por até 1 mês.","pastel assado queijo massa arroz festa lanche"),
RS(15,"Bolinhas de queijo assadas","Salgados assados","Bolinhas macias de polvilho e queijo, assadas em vez de fritas, parecidas com bolinhas de queijo de festa.","30 bolinhas",20,25,"200 °C",
["250 g (2 e 1/2 xícaras)|polvilho doce","100 g|queijo minas padrão ralado","60 g|queijo parmesão ralado","2 unidades|ovos","80 ml|óleo de girassol","80 ml|leite","3 g (1/2 colher de chá)|sal","5 g (1 colher de chá)|fermento químico em pó"],
["Preaqueça o forno a 200 °C e forre uma assadeira com papel-manteiga.","Misture o polvilho, os queijos, o sal e o fermento. Junte os ovos, o óleo e o leite e mexa até formar uma massa macia e úmida. Ela deve soltar das mãos, mas ficar um pouco grudenta.","Com as mãos untadas, faça 30 bolinhas de cerca de 25 g e disponha na assadeira com 3 cm de distância.","Asse por 22 a 25 minutos, até as bolinhas ficarem douradas por fora e firmes. Espere 5 minutos antes de servir."],
["Se a massa ficar muito mole para modelar, junte 1 colher de sopa de polvilho por vez.","Bolinhas muito grandes ficam cruas no meio. Mantenha o tamanho de cerca de 25 g.","Confira no rótulo o polvilho, os queijos e o fermento."],
"Até 3 dias na geladeira, em recipiente fechado. Congela por até 2 meses.","bolinha queijo polvilho doce festa assado petisco"),
RS(16,"Kibe assado de abóbora e carne","Salgados assados","Kibe de forno sem trigo, com abóbora e carne moída, de textura firme e sabor suave de hortelã.","1 forma de 22 x 30 cm (12 pedaços)",45,40,"200 °C",
["500 g|carne moída (patinho)","400 g|abóbora cabotiá cozida e amassada","60 g (1/2 xícara)|fécula de batata","1 unidade|cebola ralada","2 dentes|alho amassados","2 colheres de sopa|hortelã picada","1 colher de chá|canela em pó","5 g (1 colher de chá)|sal","2 colheres de sopa|azeite","200 g|queijo mussarela em fatias","1 colher de sopa|azeite, para untar"],
["Preaqueça o forno a 200 °C e unte uma forma de 22 x 30 cm.","Misture a abóbora amassada e bem escorrida com a carne crua, a fécula, a cebola, o alho, a hortelã, a canela e o sal. Amasse até formar uma massa homogênea que se mantenha unida.","Espalhe metade da massa na forma, pressionando bem. Cubra com as fatias de queijo e finalize com o restante da massa.","Alise o topo, regue com o azeite e marque losangos com a ponta de uma faca.","Asse por 35 a 40 minutos, até dourar e a carne estar totalmente cozida, sem partes rosadas ao cortar. Espere 10 minutos antes de cortar."],
["Escorra bem a abóbora, ou o kibe fica mole.","A carne precisa chegar a cozimento completo. Corte um pedaço do centro para conferir.","Confira no rótulo a carne moída industrializada e o queijo. Este kibe é feito sem trigo; não o substitua por trigo para quibe."],
"Até 3 dias na geladeira, em recipiente fechado. Congela por até 2 meses. Reaqueça até ficar bem quente.","kibe assado abóbora carne hortelã festa jantar sem trigo"),
RS(17,"Pão de batata recheado com frango","Salgados assados","Pãezinhos macios de batata recheados com frango cremoso, bons para lanches e festas.","10 pãezinhos",50,30,"190 °C",
["500 g|batatas cozidas e espremidas","150 g (1 e 1/4 de xícara)|fécula de batata","60 g (1/2 xícara)|polvilho doce","40 g|manteiga","1 unidade|ovo","5 g (1 colher de chá)|sal","250 g|peito de frango cozido e desfiado","1/2 unidade|cebola picada","1 colher de sopa|azeite","100 g (1/2 xícara)|requeijão cremoso","1 colher de sopa|salsinha picada","1 unidade|gema, para pincelar"],
["Faça o recheio: refogue a cebola no azeite por 3 minutos, junte o frango, sal a gosto e cozinhe por 2 minutos. Desligue, misture o requeijão e a salsinha e deixe esfriar.","Misture a batata, a fécula, o polvilho, a manteiga, o ovo e o sal até formar uma massa macia e lisa, que não gruda nas mãos.","Preaqueça o forno a 190 °C e forre uma assadeira com papel-manteiga.","Divida a massa em 10 porções de cerca de 85 g. Abra cada uma em disco de 9 cm, coloque 1 colher de sopa de recheio e feche como uma trouxinha, apertando bem.","Disponha com a emenda para baixo, pincele com a gema e asse por 28 a 30 minutos, até dourar. Espere 10 minutos antes de comer."],
["Não exagere no recheio, para a trouxinha não abrir.","Se a massa ficar pegajosa, deixe na geladeira por 15 minutos antes de modelar.","Confira no rótulo o requeijão, o polvilho e a fécula."],
"Até 3 dias na geladeira, em recipiente fechado. Congela já assado por até 2 meses.","pão batata recheado frango requeijão lanche festa assado"),
RS(18,"Empanada assada de frango e azeitona","Salgados assados","Empanadas de massa amanteigada assadas, com recheio de frango temperado, azeitonas e ovo cozido.","10 empanadas",50,25,"200 °C",
["200 g (1 e 1/3 de xícara)|farinha de arroz branca","80 g (2/3 de xícara)|fécula de batata","100 g|manteiga gelada","1 unidade|ovo","5 g (1 colher de chá)|sal","2 a 3 colheres de sopa|água gelada","300 g|peito de frango cozido e desfiado","1/2 unidade|cebola picada","1 unidade|tomate sem sementes, picado","50 g|azeitonas verdes sem caroço, picadas","2 unidades|ovos cozidos, picados","1 colher de chá|páprica doce","1 colher de sopa|azeite","1 unidade|gema, para pincelar"],
["Faça a massa: misture a farinha, a fécula e o sal. Esfarele a manteiga, junte o ovo e a água até formar uma massa macia. Embrulhe e leve à geladeira por 30 minutos.","Refogue a cebola no azeite por 3 minutos, junte o tomate, a páprica e o frango e cozinhe por 5 minutos, até secar. Desligue, misture as azeitonas e o ovo cozido e deixe esfriar.","Preaqueça o forno a 200 °C e forre uma assadeira com papel-manteiga.","Abra a massa entre dois plásticos, com 3 mm de espessura. Corte discos de 12 cm.","Coloque 1 colher de sopa de recheio em cada disco, dobre ao meio e feche as bordas com um garfo.","Pincele com a gema e asse por 22 a 25 minutos, até dourar. Espere 5 minutos antes de servir."],
["Recheio frio evita que a massa amoleça.","A massa sem glúten é mais frágil: abra entre dois plásticos e vire sobre a mão, em vez de erguer da bancada.","Confira no rótulo as azeitonas em conserva, a páprica, a fécula e a farinha de arroz."],
"Até 3 dias na geladeira, em recipiente fechado. Congela por até 2 meses.","empanada assada frango azeitona ovo festa lanche massa amanteigada"),
RS(19,"Palitos de queijo e ervas","Salgados assados","Palitos finos e crocantes de polvilho, queijo e ervas, para petiscar ou acompanhar sopas.","40 palitos",25,20,"200 °C",
["200 g (2 xícaras)|polvilho azedo","50 g|queijo parmesão ralado","60 ml|óleo de girassol","60 ml|leite","1 unidade|ovo","1 colher de chá|orégano","1/2 colher de chá|alho em pó","3 g (1/2 colher de chá)|sal"],
["Preaqueça o forno a 200 °C e forre uma assadeira com papel-manteiga.","Ferva o leite com o óleo e o sal e despeje sobre o polvilho. Mexa e deixe amornar por 10 minutos.","Junte o ovo, o parmesão, o orégano e o alho em pó e amasse até formar uma massa lisa e maleável.","Faça rolinhos finos de 1 cm de espessura e 10 cm de comprimento e disponha na assadeira.","Asse por 18 a 20 minutos, até dourar e ficar firme. Deixe esfriar para ficar crocante."],
["Palitos muito grossos ficam macios no centro. Mantenha a espessura fina.","Para um sabor diferente, troque o orégano por 1 colher de chá de páprica defumada.","Confira no rótulo o polvilho, o parmesão, o alho em pó e o orégano."],
"Até 5 dias em pote fechado, em local seco. Se amolecerem, volte ao forno a 150 °C por 5 minutos.","palito queijo ervas polvilho petisco crocante assado"),
RS(20,"Rocambole salgado de presunto e queijo","Salgados assados","Rocambole de massa macia de batata, recheado com presunto e queijo, em fatias bonitas para festas.","1 rocambole (10 fatias)",50,30,"190 °C",
["500 g|batatas cozidas e espremidas","100 g (cerca de 3/4 de xícara)|fécula de batata","40 g|manteiga","2 unidades|ovos","5 g (1 colher de chá)|sal","200 g|presunto fatiado","200 g|queijo mussarela fatiado","100 g|requeijão cremoso","2 colheres de sopa|fécula, para a bancada","1 colher de sopa|manteiga, para untar"],
["Preaqueça o forno a 190 °C e forre uma assadeira de 30 x 40 cm com papel-manteiga untado.","Misture a batata, a fécula, a manteiga, os ovos e o sal até formar uma massa macia e lisa.","Abra a massa sobre a assadeira, com 7 mm de espessura, num retângulo uniforme.","Asse por 15 minutos, até firmar e dourar levemente.","Retire do forno e, ainda morna, vire sobre um pano limpo polvilhado com fécula. Retire o papel.","Espalhe o requeijão, cubra com o presunto e o queijo e enrole, com ajuda do pano, apertando de leve.","Volte ao forno por 10 a 12 minutos, até o queijo derreter e a superfície dourar. Espere 10 minutos antes de cortar."],
["Enrole a massa ainda morna, para não rachar.","Cortar com faca de serra e lâmina limpa dá fatias mais bonitas.","Confira no rótulo o presunto, o requeijão e o queijo fatiado."],
"Até 3 dias na geladeira, em recipiente fechado. Congela fatiado por até 2 meses.","rocambole salgado presunto queijo batata festa lanche"),
RSC("fritar em óleo a 170 °C por 3 a 4 minutos, em porções pequenas",21,"Bolinho de arroz com queijo","Bolinhos e fritos","Bolinhos dourados e crocantes por fora, macios por dentro, para aproveitar o arroz que sobrou.","24 bolinhos",20,null,null,
["400 g (2 xícaras)|arroz branco cozido e frio","2 unidades|ovos","60 g (1/2 xícara)|queijo parmesão ralado","40 g (1/3 de xícara)|amido de milho","1/2 unidade|cebola ralada","2 colheres de sopa|salsinha picada","3 g (1/2 colher de chá)|sal","5 g (1 colher de chá)|fermento químico em pó","500 ml|óleo de girassol, para fritar"],
["Misture o arroz, os ovos, o parmesão, a cebola, a salsinha e o sal. Amasse levemente com um garfo para soltar os grãos que estão colados.","Junte o amido de milho e o fermento e mexa. A massa deve ficar úmida e firme o suficiente para ser moldada com duas colheres, sem escorrer.","Aqueça o óleo a 170 °C numa panela funda. Sem termômetro, teste com um pedacinho de massa: ele deve subir à superfície em poucos segundos, com bolhas pequenas.","Frite colheradas de massa por 3 a 4 minutos, virando de vez em quando, até ficarem bem douradas.","Escorra sobre papel-toalha e sirva morno."],
["Se os bolinhos desmancharem no óleo, junte 1 colher de sopa de amido à massa.","Não encha a panela de bolinhos: o óleo esfria e eles absorvem gordura.","Cuidado com o óleo quente: seque bem as mãos e os utensílios e nunca deixe a panela sem vigilância. Confira no rótulo o parmesão e o amido."],
"Até 2 dias na geladeira, em recipiente fechado. Reaqueça no forno a 200 °C por 8 minutos para voltarem a ficar crocantes.","bolinho arroz queijo frito sobras petisco lanche"),
RSC("fritar em óleo a 170 °C por 4 a 5 minutos, em porções pequenas",22,"Bolinho de mandioca recheado com carne seca","Bolinhos e fritos","Bolinhos de massa de mandioca com recheio de carne seca temperada, crocantes por fora e macios por dentro.","20 bolinhos",60,null,null,
["500 g|mandioca cozida e espremida, ainda morna","30 g|manteiga","1 unidade|ovo","40 g (1/3 de xícara)|polvilho doce","3 g (1/2 colher de chá)|sal","250 g|carne seca dessalgada, cozida e desfiada","1/2 unidade|cebola picada","1 dente|alho amassado","1 colher de sopa|azeite","1 colher de sopa|cebolinha picada","500 ml|óleo de girassol, para fritar"],
["Dessalgue a carne seca de véspera, trocando a água 3 vezes, e cozinhe até ficar macia. Desfie e refogue com a cebola e o alho no azeite por 5 minutos, até secar. Junte a cebolinha e deixe esfriar.","Misture a mandioca espremida com a manteiga, o ovo, o polvilho e o sal até formar uma massa lisa, sem fios. Se grudar, junte polvilho aos poucos.","Com as mãos untadas, pegue 1 colher de sopa de massa, achate na palma, coloque 1 colher de chá de carne seca e feche, moldando um bolinho.","Aqueça o óleo a 170 °C e frite poucos bolinhos por vez por 4 a 5 minutos, até ficarem dourados.","Escorra sobre papel-toalha e sirva morno."],
["A carne seca costuma ser bem salgada. Prove antes de temperar a massa e só acerte o sal depois.","Mandioca sem os fios grossos dá massa mais lisa e bolinhos que não abrem.","Cuidado com o óleo quente. Confira no rótulo a carne seca, o polvilho e o óleo."],
"Até 2 dias na geladeira, em recipiente fechado. Congele crus, em bandeja, antes de fritar, por até 1 mês, e frite ainda congelados.","bolinho mandioca carne seca frito festa petisco"),
RSC("fritar em óleo a 170 °C por 4 a 5 minutos, em porções pequenas",23,"Coxinha de batata com frango","Bolinhos e fritos","Coxinhas de massa macia de batata, recheadas com frango cremoso e empanadas com farinha de rosca sem glúten.","20 coxinhas pequenas",70,null,null,
["500 g|batatas cozidas e espremidas, ainda mornas","100 g (cerca de 3/4 de xícara)|fécula de batata","30 g|manteiga","3 g (1/2 colher de chá)|sal","300 g|peito de frango cozido e desfiado","1/2 unidade|cebola picada","1 dente|alho amassado","1 colher de sopa|azeite","100 g (1/2 xícara)|requeijão cremoso","1 colher de sopa|salsinha picada","2 unidades|ovos batidos","100 g (cerca de 1 xícara)|farinha de rosca sem glúten","500 ml|óleo de girassol, para fritar"],
["Faça o recheio: refogue a cebola no azeite por 3 minutos, junte o alho e o frango e cozinhe por 3 minutos. Desligue, misture o requeijão e a salsinha, acerte o sal e deixe esfriar por 30 minutos na geladeira.","Misture a batata, a fécula, a manteiga e o sal até formar uma massa macia e lisa, que não grude nas mãos. Se grudar, junte 1 colher de sopa de fécula por vez.","Pegue cerca de 1 colher de sopa cheia de massa, abra na palma da mão, coloque 1 colher de chá de recheio, feche e modele em formato de gota.","Passe cada coxinha nos ovos batidos e depois na farinha de rosca, pressionando. Para uma crosta mais firme, repita a passagem pelo ovo e pela farinha de rosca.","Leve à geladeira por 15 minutos para firmar.","Aqueça o óleo a 170 °C e frite poucas coxinhas por vez por 4 a 5 minutos, até dourarem.","Escorra sobre papel-toalha e espere 5 minutos antes de comer."],
["O recheio precisa estar frio, ou a massa rompe ao modelar.","Confira muito bem a farinha de rosca: a comum contém trigo. Use apenas marcas sem glúten, ou triture flocos de arroz.","Cuidado com o óleo quente. Confira no rótulo o requeijão e a fécula."],
"Até 2 dias na geladeira, em recipiente fechado, pois o recheio é perecível. Congele cruas e empanadas por até 1 mês; frite ainda congeladas, em fogo um pouco mais baixo.","coxinha batata frango frita festa salgado"),
RSC("fritar em óleo a 170 °C por 3 minutos, em porções pequenas",24,"Risole de carne com massa de crepe","Bolinhos e fritos","Risoles de massa fina de crepe, recheados com carne moída e empanados, crocantes por fora.","12 risoles",60,null,null,
["240 ml (1 xícara)|leite","2 unidades|ovos","80 g (2/3 de xícara)|amido de milho","60 g (cerca de 1/3 de xícara)|farinha de arroz branca","1 colher de sopa|óleo de girassol","3 g (1/2 colher de chá)|sal","300 g|carne moída (patinho)","1/2 unidade|cebola picada","1 dente|alho amassado","1 colher de sopa|azeite","1 colher de sopa|extrato de tomate","1 colher de sopa|salsinha picada","2 unidades|ovos batidos, para empanar","100 g (cerca de 1 xícara)|farinha de rosca sem glúten","500 ml|óleo de girassol, para fritar"],
["Faça o recheio: refogue a cebola e o alho no azeite por 3 minutos, junte a carne e mexa por 6 minutos, até secar e dourar. Acrescente o extrato de tomate, sal e a salsinha e cozinhe por 2 minutos. Deixe esfriar.","Bata no liquidificador o leite, os ovos, o amido, a farinha de arroz, o óleo e o sal. A massa deve ficar bem fluida, como massa de crepe.","Aqueça uma frigideira antiaderente de 18 cm, unte levemente e despeje 3 colheres de sopa de massa, inclinando para espalhar. Cozinhe por 1 minuto de um lado, vire e cozinhe por 30 segundos. Repita até obter 12 crepes.","Coloque 1 colher de sopa de recheio no centro de cada crepe, dobre as laterais e enrole como um envelope.","Passe nos ovos batidos e na farinha de rosca, pressionando. Leve à geladeira por 15 minutos.","Aqueça o óleo a 170 °C e frite por 3 minutos, até dourar. Escorra sobre papel-toalha."],
["O crepe sem glúten rasga com facilidade. Vire-o com uma espátula larga e sem pressa.","Não deixe sobrar recheio nas bordas, ou o risole abre no óleo.","Cuidado com o óleo quente. Confira no rótulo a farinha de rosca, o amido e o extrato de tomate."],
"Até 2 dias na geladeira, em recipiente fechado. Congele crus e empanados por até 1 mês e frite ainda congelados.","risole carne crepe frito festa salgado"),
RSC("fritar em óleo a 170 °C por 3 a 4 minutos, em porções pequenas",25,"Bolinho de bacalhau com batata","Bolinhos e fritos","Bolinhos tradicionais de bacalhau desfiado com batata e salsinha, crocantes por fora e macios por dentro.","20 bolinhos",45,null,null,
["300 g|bacalhau dessalgado e cozido, desfiado","400 g|batatas cozidas e espremidas","1/2 unidade|cebola ralada","2 unidades|ovos","3 colheres de sopa|salsinha picada","1 colher de sopa|azeite","pimenta-do-reino a gosto|tempero","500 ml|óleo de girassol, para fritar"],
["Dessalgue o bacalhau por 24 horas na geladeira, trocando a água 4 vezes. Cozinhe em água por 10 minutos, escorra, retire peles e espinhas e desfie.","Refogue a cebola no azeite por 2 minutos e deixe esfriar.","Misture a batata, o bacalhau, a cebola, a salsinha, os ovos e a pimenta. Prove antes de colocar sal, pois o bacalhau já é salgado.","Com duas colheres de sopa untadas, modele os bolinhos em formato oval.","Aqueça o óleo a 170 °C e frite poucos bolinhos por vez por 3 a 4 minutos, até dourarem por igual.","Escorra sobre papel-toalha e sirva morno."],
["Batata bem escorrida e seca evita que os bolinhos desmanchem.","Confira com atenção as espinhas depois de desfiar o bacalhau.","Cuidado com o óleo quente. Confira no rótulo o bacalhau e a salsinha desidratada, se usar. Peixe é perecível: não deixe a massa fora da geladeira por mais de 1 hora."],
"Até 2 dias na geladeira, em recipiente fechado. Congele crus por até 1 mês. Reaqueça no forno até ficarem bem quentes.","bolinho bacalhau batata frito petisco peixe festa"),
RSC("fritar em óleo a 180 °C por 3 a 4 minutos, em porções pequenas",26,"Falafel de grão-de-bico","Bolinhos e fritos","Bolinhos de grão-de-bico com ervas e cominho, crocantes por fora e verdes por dentro. Servem para lanche e prato.","20 bolinhos",25,null,null,
["250 g (1 e 1/4 de xícara)|grão-de-bico seco, de molho por 12 horas","1 unidade|cebola pequena","4 dentes|alhos","1 xícara (cerca de 30 g)|salsinha e coentro frescos","1 colher de chá|cominho em pó","5 g (1 colher de chá)|sal","1 colher de chá|fermento químico em pó","2 colheres de sopa|farinha de grão-de-bico","500 ml|óleo de girassol, para fritar"],
["Escorra o grão-de-bico depois do molho. Ele deve estar hidratado e firme, não cozido.","No processador, triture a cebola, o alho e as ervas. Junte o grão-de-bico e pulse até obter uma massa granulada, com textura de farinha grossa, que se junta ao ser apertada.","Misture o cominho, o sal, o fermento e a farinha de grão-de-bico. Deixe descansar por 20 minutos.","Modele 20 bolinhos de 3 cm, apertando bem.","Aqueça o óleo a 180 °C e frite poucos bolinhos por vez por 3 a 4 minutos, até dourar por igual.","Escorra sobre papel-toalha e sirva com molho de iogurte ou tahine."],
["Não use grão-de-bico cozido ou de lata: a massa fica mole e desmancha no óleo.","Para uma versão assada, pincele com azeite e asse a 200 °C por 25 minutos, virando na metade.","Confira no rótulo o grão-de-bico, a farinha de grão-de-bico e o cominho."],
"Até 3 dias na geladeira, em recipiente fechado. Reaqueça no forno. Congela cru por até 1 mês.","falafel grão-de-bico vegetariano frito árabe lanche"),
RSC("fritar em óleo a 170 °C por 3 a 4 minutos, em porções pequenas",27,"Bolinho de milho verde frito","Bolinhos e fritos","Bolinhos macios de milho verde com queijo, de sabor doce e salgado, bons para o lanche da tarde.","20 bolinhos",20,null,null,
["400 g (cerca de 2 latas, escorridas)|milho verde","2 unidades|ovos","60 g (1/2 xícara)|queijo parmesão ralado","60 g (1/2 xícara)|amido de milho","40 g (1/4 de xícara)|fubá fino","5 g (1 colher de chá)|fermento químico em pó","3 g (1/2 colher de chá)|sal","1 colher de sopa|cebolinha picada","500 ml|óleo de girassol, para fritar"],
["Bata metade do milho no liquidificador com os ovos, até formar um creme com pedacinhos.","Passe para uma tigela e junte o restante do milho inteiro, o parmesão, o amido, o fubá, o sal e a cebolinha.","Misture e, por último, acrescente o fermento. A massa deve ficar espessa e cair da colher em pedaços, não escorrer.","Aqueça o óleo a 170 °C e frite colheradas de massa por 3 a 4 minutos, virando, até dourarem.","Escorra sobre papel-toalha e sirva morno."],
["Se a massa ficar muito mole, junte 1 colher de sopa de amido de milho por vez.","Escorra bem o milho em lata para não aguar a massa.","Cuidado com o óleo quente. Confira no rótulo o milho em lata, o fubá, o parmesão e o fermento."],
"Até 2 dias na geladeira, em recipiente fechado. Reaqueça no forno ou na air fryer.","bolinho milho verde frito lanche café queijo"),
RSC("fritar em óleo a 170 °C por 3 a 4 minutos, em porções pequenas",28,"Croquete de carne","Bolinhos e fritos","Croquetes de carne em massa cremosa de leite, empanados e crocantes por fora, macios por dentro.","20 croquetes",90,null,null,
["400 g|carne cozida (patinho ou acém) moída ou muito bem desfiada","1/2 unidade|cebola picada","1 dente|alho amassado","2 colheres de sopa|azeite","40 g|manteiga","60 g (1/2 xícara)|amido de milho","480 ml (2 xícaras)|leite","1 pitada|noz-moscada","2 colheres de sopa|salsinha picada","2 unidades|ovos batidos, para empanar","100 g (cerca de 1 xícara)|farinha de rosca sem glúten","500 ml|óleo de girassol, para fritar"],
["Refogue a cebola e o alho no azeite por 3 minutos, junte a carne e cozinhe por 3 minutos. Reserve.","Prepare a massa: derreta a manteiga numa panela, junte o amido dissolvido no leite frio e mexa sem parar em fogo médio por 5 a 6 minutos, até formar uma massa espessa, que solta do fundo da panela.","Acrescente a carne, a noz-moscada, a salsinha, sal e pimenta. Cozinhe por 2 minutos, mexendo.","Espalhe numa travessa untada, cubra com plástico encostado na massa e leve à geladeira por 2 horas, até ficar firme.","Modele croquetes de 6 cm com as mãos untadas, passe nos ovos batidos e na farinha de rosca. Repita, se quiser mais crocância.","Aqueça o óleo a 170 °C e frite por 3 a 4 minutos, até dourar. Escorra e sirva morno."],
["A massa precisa estar bem gelada para modelar.","Se o croquete abrir no óleo, empane duas vezes e frite em óleo bem quente.","Cuidado com o óleo quente. Confira no rótulo a farinha de rosca, o amido e a carne, se for industrializada."],
"Até 2 dias na geladeira, em recipiente fechado. Congele crus e empanados por até 1 mês.","croquete carne frito festa salgado empanado"),
RSC("fritar em frigideira com 1 cm de óleo, 3 minutos de cada lado",29,"Bolinho de abobrinha e queijo na frigideira","Bolinhos e fritos","Bolinhos finos de abobrinha ralada e queijo, fritos em pouco óleo, para o lanche ou como acompanhamento.","12 bolinhos",20,null,null,
["500 g (3 unidades médias)|abobrinhas raladas","5 g (1 colher de chá)|sal, para as abobrinhas","2 unidades|ovos","60 g (1/2 xícara)|fécula de batata","60 g|queijo parmesão ralado","1 colher de sopa|hortelã ou salsinha picada","pimenta-do-reino a gosto|tempero","100 ml|óleo de girassol, para fritar"],
["Misture a abobrinha ralada com o sal e deixe por 10 minutos. Aperte bem num pano limpo, até sair quase toda a água.","Numa tigela, misture a abobrinha, os ovos, a fécula, o parmesão, a hortelã e a pimenta, até formar uma massa grossa e úmida.","Aqueça o óleo numa frigideira antiaderente grande, em fogo médio.","Despeje colheradas de massa, achate de leve e frite por 3 minutos de cada lado, até dourarem.","Escorra sobre papel-toalha e sirva morno."],
["Quanto mais água sair da abobrinha, mais crocante fica o bolinho.","Não mexa nos bolinhos logo ao colocá-los, para formar uma crosta antes de virar.","Cuidado com o óleo quente. Confira no rótulo a fécula e o parmesão ralado."],
"Até 2 dias na geladeira, em recipiente fechado. Reaqueça na frigideira ou no forno.","bolinho abobrinha queijo frigideira vegetariano lanche"),
RS(30,"Nuggets de frango com crosta de fubá","Petiscos","Nuggets assados, com crosta crocante de fubá e queijo, sem fritura. Muito bons para crianças e lanches.","24 nuggets",35,20,"200 °C",
["600 g|peito de frango, em pedaços de 4 cm","2 unidades|ovos","1 colher de sopa|leite","100 g (2/3 de xícara)|fubá fino","40 g|queijo parmesão ralado","1 colher de chá|páprica doce","1/2 colher de chá|alho em pó","5 g (1 colher de chá)|sal","2 colheres de sopa|azeite"],
["Preaqueça o forno a 200 °C e forre uma assadeira com papel-manteiga untado com azeite.","Tempere o frango com metade do sal. Bata os ovos com o leite num prato fundo.","Misture num segundo prato o fubá, o parmesão, a páprica, o alho em pó e o restante do sal.","Passe cada pedaço no ovo e depois na mistura de fubá, pressionando bem para aderir.","Disponha na assadeira sem encostar, regue com o azeite e asse por 10 minutos. Vire e asse por mais 8 a 10 minutos.","Estão prontos quando a crosta estiver dourada e o frango firme, sem partes rosadas ao cortar um pedaço no meio."],
["Para uma crosta mais crocante, ligue o forno em modo grill nos últimos 2 minutos.","Pedaços uniformes cozinham ao mesmo tempo. Corte-os do mesmo tamanho.","Confira no rótulo o fubá, o parmesão ralado e o alho em pó."],
"Até 3 dias na geladeira, em recipiente fechado. Congela assado por até 2 meses.","nuggets frango fubá assado crocante criança lanche petisco"),
RS(31,"Panqueca de carne moída gratinada","Panquecas e crepes","Panquecas macias recheadas com carne moída e molho de tomate, gratinadas com queijo.","10 panquecas (5 porções)",50,15,"200 °C",
["300 ml (1 e 1/4 de xícara)|leite","2 unidades|ovos","90 g (cerca de 2/3 de xícara)|farinha de arroz branca","50 g (cerca de 1/3 de xícara)|fécula de batata","1 colher de sopa|óleo de girassol","3 g (1/2 colher de chá)|sal","400 g|carne moída (patinho)","1/2 unidade|cebola picada","2 dentes|alho amassados","1 colher de sopa|azeite","400 g (1 lata ou caixinha)|tomate pelado picado","1 colher de sopa|salsinha picada","150 g|queijo mussarela fatiado","1 colher de chá|óleo, para untar a frigideira"],
["Faça o molho: refogue a cebola e o alho no azeite por 3 minutos, junte a carne e mexa em fogo alto por 6 minutos, até dourar. Acrescente o tomate, sal e pimenta e cozinhe por 10 minutos, até secar e formar um molho espesso. Junte a salsinha e reserve metade do molho para cobrir.","Bata no liquidificador o leite, os ovos, a farinha de arroz, a fécula, o óleo e o sal. A massa deve ficar fina e fluida, como creme de leite fresco.","Unte levemente uma frigideira de 20 cm e aqueça em fogo médio. Despeje 1/2 concha de massa, gire para espalhar e cozinhe por 1 a 2 minutos, até soltar as bordas e secar o topo. Vire e cozinhe por 30 segundos. Repita até obter 10 panquecas.","Preaqueça o forno a 200 °C. Recheie cada panqueca com a carne, enrole e disponha numa travessa.","Cubra com o molho reservado e as fatias de queijo e asse por 15 minutos, até o queijo derreter e dourar."],
["A primeira panqueca costuma ser a mais difícil. Se quebrar, não desanime: ajuste o fogo e continue.","Se a massa engrossar ao descansar, afine com 1 colher de sopa de leite.","Confira no rótulo o tomate pelado, a mussarela e a fécula. Evite molhos de tomate prontos com amido modificado sem informação."],
"Até 3 dias na geladeira, em recipiente fechado. Congela por até 2 meses, já recheada.","panqueca carne moída gratinada molho tomate almoço jantar"),
RS(32,"Crepe de frango com requeijão","Panquecas e crepes","Crepes finos de polvilho doce, com recheio cremoso de frango e requeijão, para almoço leve ou jantar.","8 crepes",40,null,null,
["240 ml (1 xícara)|leite","2 unidades|ovos","100 g (cerca de 3/4 de xícara)|polvilho doce","30 g (cerca de 3 colheres de sopa)|farinha de arroz branca","1 colher de sopa|óleo de girassol","3 g (1/2 colher de chá)|sal","300 g|peito de frango cozido e desfiado","1/2 unidade|cebola picada","1 colher de sopa|azeite","150 g (3/4 de xícara)|requeijão cremoso","1 colher de sopa|salsinha picada","1 colher de chá|óleo, para untar a frigideira"],
["Faça o recheio: refogue a cebola no azeite por 3 minutos, junte o frango e cozinhe por 3 minutos. Desligue, misture o requeijão, a salsinha, sal e pimenta.","Bata no liquidificador o leite, os ovos, o polvilho, a farinha de arroz, o óleo e o sal por 1 minuto. Deixe descansar por 10 minutos.","Unte levemente uma frigideira de 20 cm e aqueça em fogo médio. Despeje 1/2 concha de massa e gire para espalhar. Cozinhe por 1 a 2 minutos, até secar o topo e soltar as bordas. Vire e cozinhe por mais 30 segundos.","Coloque 2 colheres de sopa de recheio em cada crepe e enrole. Sirva quente, ou aqueça no forno por 5 minutos."],
["A massa com polvilho assenta no fundo. Mexa antes de cada concha.","Cozinhe cada crepe em fogo médio. Fogo alto queima por fora e deixa cru por dentro.","Confira no rótulo o polvilho, o requeijão e o óleo."],
"Até 3 dias na geladeira, em recipiente fechado. Reaqueça no micro-ondas ou no forno.","crepe frango requeijão polvilho almoço jantar leve"),
RS(33,"Panqueca verde de espinafre e ricota","Panquecas e crepes","Panquecas de massa verde com espinafre, recheadas com ricota e queijo, gratinadas com molho de tomate.","10 panquecas (5 porções)",50,15,"200 °C",
["60 g|espinafre fresco, sem os talos","300 ml|leite","2 unidades|ovos","80 g (1/2 xícara)|farinha de arroz branca","40 g (1/3 de xícara)|fécula de batata","1 colher de sopa|óleo de girassol","3 g (1/2 colher de chá)|sal","300 g|ricota fresca amassada","100 g|queijo mussarela ralado","1/2 unidade|cebola picada","1 colher de sopa|azeite","1 pitada|noz-moscada","300 ml|molho de tomate caseiro","1 colher de chá|óleo, para untar a frigideira"],
["Faça o recheio: refogue a cebola no azeite por 3 minutos. Misture com a ricota, metade da mussarela, a noz-moscada, sal e pimenta.","Bata no liquidificador o espinafre, o leite, os ovos, a farinha de arroz, a fécula, o óleo e o sal, até a massa ficar lisa e verde, sem pedaços de folha.","Unte levemente uma frigideira de 20 cm e aqueça. Despeje 1/2 concha de massa, gire e cozinhe por 1 a 2 minutos de um lado e 30 segundos do outro, até obter 10 panquecas.","Preaqueça o forno a 200 °C. Recheie as panquecas, enrole e disponha numa travessa.","Cubra com o molho de tomate e a mussarela restante e asse por 15 minutos, até gratinar."],
["O espinafre cru batido no liquidificador deixa a massa colorida sem sabor forte.","Se a ricota estiver aguada, escorra por 15 minutos numa peneira.","Confira no rótulo a ricota, a mussarela e o molho de tomate. Prefira queijos em peça."],
"Até 3 dias na geladeira, em recipiente fechado. Congela por até 2 meses.","panqueca espinafre ricota verde gratinada vegetariana almoço jantar"),
RS(34,"Tapioca recheada de queijo e tomate","Lanches rápidos","Tapioca quentinha com queijo derretido e tomate, pronta em poucos minutos, sem forno e sem farinha de trigo.","4 tapiocas",10,null,null,
["240 g (4 porções de 60 g)|goma de tapioca hidratada","200 g|queijo minas frescal ou mussarela fatiada","2 unidades|tomates em rodelas finas","1 colher de chá|orégano","1 pitada|sal"],
["Aqueça uma frigideira antiaderente de 20 cm em fogo médio, sem óleo.","Espalhe 60 g de goma numa camada fina e uniforme, formando um disco. Cozinhe por 1 a 2 minutos, até a goma ficar firme e unir.","Coloque o queijo e o tomate numa metade, polvilhe orégano e sal e dobre com uma espátula.","Cozinhe por mais 1 minuto, até o queijo derreter. Repita com o restante."],
["Se a goma estiver seca e esfarelar, borrife um pouco de água e misture com os dedos antes de usar.","Se estiver úmida, deixe descansar na peneira por 10 minutos.","Confira no rótulo a goma de tapioca e o queijo. Marcas diferentes variam na hidratação."],
"Consuma na hora. A goma hidratada pode ser guardada em pote fechado na geladeira por até 3 dias.","tapioca queijo tomate rápido sem forno lanche café"),
RS(35,"Wrap de batata-doce na frigideira","Lanches rápidos","Massas finas e flexíveis de batata-doce, feitas na frigideira, para enrolar com frango, folhas e legumes.","6 wraps",30,null,null,
["300 g|batata-doce cozida e amassada","60 g (cerca de 1/2 xícara)|polvilho doce","1 unidade|ovo","3 g (1/2 colher de chá)|sal","1 colher de sopa|polvilho doce, para a bancada","200 g|peito de frango grelhado em tiras","2 folhas|alface","1 unidade|tomate em fatias","50 g|cenoura ralada","3 colheres de sopa|iogurte natural"],
["Misture a batata-doce, o polvilho, o ovo e o sal até formar uma massa macia, que não grude nas mãos.","Divida em 6 bolinhas. Abra cada uma entre dois plásticos polvilhados, formando discos finos de 16 cm, com 2 mm de espessura.","Aqueça uma frigideira antiaderente em fogo médio, sem óleo. Cozinhe cada disco por 1 a 2 minutos de cada lado, até aparecerem manchas douradas e a massa ficar firme.","Recheie com o frango, a alface, o tomate, a cenoura e o iogurte e enrole imediatamente."],
["Os discos ficam flexíveis enquanto mornos. Enrole antes de esfriarem.","Se rachar, a massa está seca: junte 1 colher de sopa de água à massa.","Confira no rótulo o polvilho doce e o iogurte."],
"Os discos sem recheio duram até 2 dias na geladeira, em recipiente fechado. Aqueça na frigideira antes de rechear. Montados, consuma no mesmo dia.","wrap batata-doce frigideira lanche saudável frango"),
RS(36,"Crepioca de frango e orégano","Lanches rápidos","Massa de ovo e tapioca feita em frigideira, recheada com frango temperado. Prática, rica em proteínas e sem forno.","2 crepiocas",15,null,null,
["2 unidades|ovos","4 colheres de sopa (cerca de 60 g)|goma de tapioca hidratada","1 colher de sopa|leite","1 pitada|sal","100 g|peito de frango cozido e desfiado","2 colheres de sopa|requeijão cremoso","1 colher de chá|orégano","1 colher de chá|azeite, para untar a frigideira"],
["Misture o frango com o requeijão, o orégano, sal e pimenta.","Bata os ovos com o leite e o sal. Junte a goma e misture até dissolver.","Aqueça uma frigideira de 20 cm untada com azeite em fogo médio. Despeje metade da massa e cozinhe por 2 minutos, até secar a superfície e soltar as bordas.","Vire e cozinhe por 1 minuto. Coloque metade do recheio, dobre e sirva quente. Repita com o restante."],
["Se a massa grudar, aqueça melhor a frigideira antes de despejar.","Para uma versão vegetariana, troque o frango por queijo e tomate.","Confira no rótulo a goma de tapioca, o requeijão e o orégano."],
"Consuma na hora. O recheio pode ser guardado por até 2 dias na geladeira.","crepioca frango ovo tapioca rápido lanche café proteína"),
RS(37,"Cuscuz paulista de frango e ovo","Lanches rápidos","Cuscuz de flocão de milho em formato de pudim, recheado com frango, ovo, ervilha e palmito. Pode ser servido morno ou frio.","1 forma de 22 cm com furo (10 fatias)",40,null,null,
["250 g (2 xícaras)|flocão de milho","400 ml|água quente","1 colher de chá|sal","300 g|peito de frango cozido e desfiado","2 unidades|ovos cozidos, em rodelas","100 g|ervilha cozida","1 vidro (300 g de palmito escorrido)|palmito picado","1 unidade|tomate sem sementes, picado","1/2 unidade|cebola picada","2 dentes|alhos amassados","3 colheres de sopa|azeite","200 ml|água do cozimento do frango","2 colheres de sopa (16 g)|amido de milho","2 colheres de sopa|salsinha picada","50 g|azeitonas, para decorar"],
["Hidrate o flocão: misture com o sal e a água quente e deixe por 10 minutos, até absorver a água. Ele deve ficar úmido e solto, não empapado.","Refogue a cebola e o alho no azeite por 3 minutos. Junte o frango, o tomate, o palmito e a ervilha e cozinhe por 3 minutos.","Dissolva o amido na água do cozimento do frango, adicione à panela e cozinhe por 3 minutos, mexendo, até engrossar. Acrescente a salsinha e acerte o sal.","Misture o flocão hidratado ao recheio aos poucos, até incorporar. Reserve 1/4 do flocão para a última camada.","Forre uma forma de 22 cm com furo, untada, com as rodelas de ovo e as azeitonas. Despeje o recheio, pressionando bem com as costas de uma colher, e cubra com o flocão reservado.","Leve à geladeira por 2 horas para firmar e desenforme virando num prato."],
["Para servir quente, leve ao micro-ondas por 2 minutos em fatias.","Compre flocão de milho sem aditivos. Esse produto às vezes é processado em locais com trigo; escolha marcas que declaram não conter glúten.","Confira no rótulo o palmito, a ervilha e as azeitonas."],
"Até 3 dias na geladeira, em recipiente fechado, pois contém ovos, frango e palmito. Não congelar.","cuscuz paulista frango ovo palmito ervilha festa almoço"),
RSC("fritar as batatas por 15 a 18 minutos e cozinhar a tortilha por 8 a 9 minutos em frigideira",38,"Tortilha espanhola de batata e cebola","Lanches rápidos","Omelete alta de batata e cebola, cozida lentamente na frigideira. Boa quente ou fria, para o lanche ou o jantar.","1 tortilha de 24 cm (6 fatias)",20,null,null,
["600 g|batatas descascadas, em fatias de 3 mm","1 unidade|cebola grande, em fatias finas","6 unidades|ovos","100 ml|azeite","5 g (1 colher de chá)|sal","1 colher de sopa|salsinha picada"],
["Aqueça o azeite numa frigideira antiaderente de 24 cm em fogo médio-baixo. Junte as batatas e a cebola com uma pitada de sal e cozinhe, mexendo de vez em quando, por 15 a 18 minutos, até ficarem macias, sem dourar.","Escorra as batatas e a cebola num escorredor, reservando 1 colher de sopa do azeite na frigideira.","Bata os ovos com o restante do sal e a salsinha. Junte a batata e a cebola e deixe descansar por 5 minutos.","Aqueça a frigideira reservada em fogo médio, despeje a mistura e alise. Cozinhe por 4 a 5 minutos, até as bordas firmarem e o fundo dourar.","Cubra com um prato, vire a tortilha e deslize de volta na frigideira. Cozinhe por mais 3 a 4 minutos, até firmar por completo, sem líquido no centro."],
["Cozinhar as batatas lentamente é o que dá a textura cremosa.","Se tiver dificuldade para virar, finalize a tortilha no forno a 180 °C por 8 minutos.","Confira no rótulo o azeite e o sal."],
"Até 2 dias na geladeira, em recipiente fechado. Consuma fria ou aqueça no micro-ondas. Não deixe mais de 2 horas fora da geladeira.","tortilha espanhola batata ovo cebola frigideira jantar lanche"),
RS(39,"Muffins de ovos com legumes","Lanches rápidos","Muffins salgados de ovos, legumes e queijo, assados em forminhas. Servem para café da manhã, lanche e lancheira.","12 muffins",20,20,"180 °C",
["8 unidades|ovos","60 ml|leite","100 g|queijo mussarela ralado","1/2 unidade|pimentão vermelho picado","60 g|espinafre picado","1/2 unidade|cebola pequena picada","1 colher de sopa|azeite","3 g (1/2 colher de chá)|sal","1 colher de sopa|azeite, para untar a forma"],
["Preaqueça o forno a 180 °C e unte 12 cavidades de uma forma de muffins, ou use forminhas de silicone.","Refogue a cebola e o pimentão no azeite por 3 minutos. Junte o espinafre e cozinhe 1 minuto, só até murchar. Deixe esfriar.","Bata os ovos com o leite e o sal. Junte os legumes e metade do queijo.","Distribua nas forminhas até 3/4 da altura e cubra com o queijo restante.","Asse por 18 a 20 minutos, até firmar e dourar de leve. Ao tocar no centro, não deve haver líquido. Espere 5 minutos para desenformar."],
["Escorra bem o espinafre refogado para os muffins não soltarem água.","Troque os legumes por sobras de brócolis, cogumelos ou abobrinha.","Confira no rótulo o queijo ralado e o leite."],
"Até 3 dias na geladeira, em recipiente fechado. Congela por até 1 mês. Reaqueça no micro-ondas por 40 segundos.","muffin ovos legumes lancheira café da manhã queijo salgado"),
RS(40,"Batata recheada gratinada com frango","Lanches rápidos","Batatas assadas com casca, recheadas com frango cremoso e gratinadas com queijo. Lanche ou refeição completa.","4 batatas",30,60,"200 °C",
["4 unidades (cerca de 300 g cada)|batatas grandes, lavadas","1 colher de sopa|azeite","3 g (1/2 colher de chá)|sal grosso","300 g|peito de frango cozido e desfiado","1/2 unidade|cebola picada","1 colher de sopa|azeite, para refogar","150 g (3/4 de xícara)|requeijão cremoso","1 colher de sopa|cebolinha picada","100 g|queijo mussarela ralado"],
["Preaqueça o forno a 200 °C. Fure as batatas com um garfo, esfregue o azeite e o sal grosso e asse por 50 a 55 minutos, até ficarem macias por dentro. Espete uma faca: ela deve entrar sem resistência.","Enquanto isso, refogue a cebola no azeite por 3 minutos, junte o frango e cozinhe por 3 minutos. Desligue e misture o requeijão e a cebolinha.","Corte uma tampa no topo de cada batata e retire a maior parte da polpa com uma colher, deixando 1 cm de parede. Amasse a polpa e misture ao recheio de frango.","Recheie as batatas, cubra com a mussarela e leve ao forno por 8 a 10 minutos, até gratinar."],
["Batatas do mesmo tamanho assam ao mesmo tempo.","Use a polpa retirada: ela deixa o recheio mais cremoso e evita desperdício.","Confira no rótulo o requeijão e a mussarela ralada."],
"Até 3 dias na geladeira, em recipiente fechado. Reaqueça no forno. Não é indicado congelar.","batata recheada gratinada frango requeijão forno almoço jantar"),
RS(41,"Chips de mandioca assados","Petiscos","Fatias finas de mandioca assadas no forno, crocantes e temperadas com páprica. Petisco leve para beliscar.","4 porções (cerca de 200 g)",20,25,"180 °C",
["500 g|mandioca crua descascada","2 colheres de sopa|azeite","3 g (1/2 colher de chá)|sal","1 colher de chá|páprica doce","1/2 colher de chá|alho em pó"],
["Preaqueça o forno a 180 °C e forre duas assadeiras com papel-manteiga.","Corte a mandioca em fatias bem finas, de cerca de 2 mm, com mandolina ou faca bem afiada, retirando o fio central.","Seque as fatias com papel-toalha. Misture com o azeite, o sal, a páprica e o alho em pó, sem deixar fatias coladas.","Disponha numa só camada, sem sobrepor. Asse por 20 a 25 minutos, virando na metade do tempo.","Estão prontas quando ficarem douradas e rígidas; elas ficam ainda mais crocantes depois de frias. Retire as que dourarem primeiro."],
["Cuidado ao fatiar com mandolina: use sempre o protetor de dedos.","Fatias de espessura desigual dourarão em tempos diferentes.","Confira no rótulo a páprica e o alho em pó."],
"Até 5 dias em pote fechado, em local seco. Se amolecerem, volte ao forno a 150 °C por 5 minutos.","chips mandioca assado crocante petisco aperitivo"),
RSC("cozinhar a polenta por 25 minutos, esfriar por 1 hora e grelhar 3 minutos de cada lado",42,"Crostini de polenta com tomate e manjericão","Petiscos","Fatias de polenta grelhadas, crocantes por fora e cremosas por dentro, cobertas com tomate temperado e manjericão.","16 crostinis",35,null,null,
["750 ml|água","150 g (1 xícara)|fubá ou polenta pré-cozida sem aditivos","5 g (1 colher de chá)|sal","20 g|manteiga","30 g|queijo parmesão ralado","2 colheres de sopa|azeite, para grelhar","3 unidades|tomates sem sementes, picados","1 dente|alho amassado","1 colher de sopa|azeite","6 folhas|manjericão rasgadas"],
["Ferva a água com o sal. Despeje o fubá em fio, mexendo com fouet, e cozinhe em fogo baixo por 25 minutos, mexendo de vez em quando, até a polenta se soltar do fundo da panela.","Desligue, junte a manteiga e o parmesão e mexa. Espalhe numa forma retangular untada, com 1,5 cm de espessura, e deixe esfriar por 1 hora, até firmar completamente.","Misture o tomate, o alho, o azeite, o manjericão e uma pitada de sal.","Desenforme a polenta e corte em retângulos de 4 x 6 cm. Aqueça o azeite numa frigideira antiaderente e grelhe os crostinis por 3 minutos de cada lado, até dourarem.","Cubra com o tomate na hora de servir."],
["A polenta precisa estar fria para cortar e grelhar sem desmanchar.","Cubra o tomate só na hora de servir, para a polenta não amolecer.","Confira no rótulo o fubá e a polenta, que podem ser processados com trigo, e o parmesão."],
"Os crostinis sem cobertura duram até 3 dias na geladeira. Grelhe antes de servir.","crostini polenta tomate manjericão petisco aperitivo festa"),
RSC("fritar em óleo a 180 °C por 2 a 3 minutos, ou assar a 200 °C por 25 minutos",43,"Dadinho de tapioca com queijo coalho","Petiscos","Cubinhos crocantes por fora e macios por dentro, de tapioca e queijo coalho. Clássico dos bares do Nordeste, servidos com geleia de pimenta.","40 dadinhos",30,null,null,
["250 g|tapioca granulada (não hidratada)","500 ml|leite","250 g|queijo coalho ralado","1 colher de chá|sal","1 colher de chá|alho em pó","500 ml|óleo de girassol, para fritar"],
["Misture a tapioca, o queijo, o sal e o alho em pó numa tigela.","Ferva o leite e despeje sobre a mistura, mexendo bem.","Deixe descansar por 10 minutos, mexa e transfira para uma forma retangular forrada com plástico, com 2 cm de espessura, pressionando com as costas de uma colher.","Leve à geladeira por 3 a 4 horas, até ficar bem firme.","Corte em cubos de 2 cm.","Frite em óleo a 180 °C, em pequenas porções, por 2 a 3 minutos, até dourar. Ou asse a 200 °C por 25 minutos, virando uma vez."],
["Use tapioca em grãos, não goma pronta. A tapioca granulada absorve o leite quente e forma uma massa firme.","Se a massa ficar mole, deixe mais tempo na geladeira antes de cortar.","Cuidado com o óleo quente. Confira no rótulo a tapioca e o queijo coalho."],
"Até 3 dias na geladeira, em recipiente fechado, antes de fritar. Congele os cubos crus por até 1 mês e frite ainda congelados.","dadinho tapioca queijo coalho petisco frito aperitivo bar"),
RS(44,"Sanduíche natural de frango com cenoura","Lanches rápidos","Sanduíche frio e leve, de frango desfiado, cenoura ralada e requeijão, no pão de forma sem glúten.","4 sanduíches",20,null,null,
["200 g|peito de frango cozido e desfiado","1 unidade|cenoura média ralada","3 colheres de sopa|requeijão cremoso","1 colher de sopa|maionese sem glúten","1 colher de sopa|salsinha ou cebolinha picada","1 colher de chá|suco de limão","8 fatias|pão de forma sem glúten","2 folhas|alface","1 unidade|tomate em fatias finas","sal e pimenta-do-reino a gosto|temperos"],
["Misture o frango, a cenoura, o requeijão, a maionese, a salsinha, o limão, sal e pimenta, até obter um creme espesso e homogêneo.","Monte os sanduíches: espalhe uma camada generosa do creme numa fatia de pão, cubra com alface e tomate e feche com outra fatia.","Corte em triângulos e sirva imediatamente, ou embrulhe em plástico e leve à geladeira."],
["Use pão de forma sem glúten da coleção de pães do aplicativo ou um comprado, e confira o rótulo.","Seque bem o tomate antes de montar, para não molhar o pão.","Confira no rótulo a maionese, o requeijão e o frango, se industrializado."],
"Consuma em até 24 horas, mantido na geladeira. Em lancheira, use bolsa térmica e consuma em até 2 horas fora da geladeira.","sanduíche natural frango cenoura requeijão lanche lancheira pão sem glúten"),
RSC("grelhar em frigideira tampada por 3 minutos de cada lado",45,"Misto quente na frigideira","Lanches rápidos","Clássico misto quente de pão sem glúten, presunto e queijo, dourado e crocante por fora.","2 sanduíches",10,null,null,
["4 fatias|pão de forma sem glúten","4 fatias|queijo mussarela","4 fatias|presunto","1 colher de sopa|manteiga"],
["Passe a manteiga numa face de cada fatia de pão.","Monte o sanduíche com a face amanteigada para fora: uma fatia, 2 fatias de queijo, 2 de presunto e a outra fatia.","Aqueça uma frigideira antiaderente em fogo baixo a médio. Coloque os sanduíches e tampe.","Grelhe por 3 minutos, vire e grelhe por mais 3 minutos, até o pão dourar e o queijo derreter."],
["Fogo baixo permite o queijo derreter sem queimar o pão.","Pães sem glúten tendem a ser mais frágeis: vire com uma espátula larga.","Confira no rótulo o pão, o presunto e o queijo fatiado."],
"Consuma na hora. Não é indicado reaquecer.","misto quente pão sem glúten presunto queijo frigideira lanche rápido"),
RSC("grelhar em frigideira por 4 minutos de cada lado",46,"Hambúrguer de feijão-preto","Lanches rápidos","Hambúrguer vegetariano de feijão-preto, firme por fora e macio por dentro. Serve no pão sem glúten, com salada ou arroz.","6 hambúrgueres",20,null,null,
["400 g (cerca de 2 xícaras)|feijão-preto cozido e bem escorrido","1/2 unidade|cebola ralada","2 dentes|alhos amassados","1 unidade|ovo","60 g (cerca de 1/3 de xícara)|farinha de arroz branca","1 colher de chá|cominho em pó","1 colher de chá|páprica doce","3 g (1/2 colher de chá)|sal","2 colheres de sopa|salsinha picada","2 colheres de sopa|azeite, para grelhar"],
["Amasse o feijão com um garfo, deixando alguns grãos inteiros.","Junte a cebola, o alho, o ovo, a farinha de arroz, o cominho, a páprica, o sal e a salsinha. A massa deve ficar úmida e firme, para modelar com as mãos sem grudar. Se estiver mole, junte 1 colher de sopa de farinha de arroz.","Divida em 6 porções e modele hambúrgueres de 8 cm e 1,5 cm de espessura. Leve à geladeira por 15 minutos.","Aqueça o azeite numa frigideira antiaderente em fogo médio. Grelhe por 4 minutos de cada lado, até formar uma crosta firme e dourada."],
["Escorra bem o feijão, ou a massa fica mole e desmancha.","Vire os hambúrgueres só uma vez, para a crosta não quebrar.","Confira no rótulo o feijão, o cominho e a páprica. Evite feijão enlatado com temperos prontos."],
"Até 3 dias na geladeira, em recipiente fechado. Congele crus, com plástico entre eles, por até 2 meses.","hambúrguer feijão-preto vegetariano frigideira lanche almoço"),
RS(47,"Homus com palitos de legumes","Petiscos","Pasta cremosa de grão-de-bico com tahine e limão, servida com palitos de cenoura, pepino e pimentão.","6 porções (cerca de 400 g de pasta)",15,null,null,
["300 g (1 e 1/2 xícara)|grão-de-bico cozido e escorrido","60 g (3 colheres de sopa)|tahine (pasta de gergelim)","45 ml (3 colheres de sopa)|suco de limão","1 dente|alho pequeno","40 ml|azeite extravirgem","60 ml|água gelada","1 colher de chá|cominho em pó","3 g (1/2 colher de chá)|sal","1 colher de chá|páprica doce, para decorar","2 unidades|cenouras em palitos","1 unidade|pepino em palitos","1 unidade|pimentão em tiras"],
["No processador, bata o tahine e o limão por 1 minuto, até ficar um creme claro.","Junte o alho, o cominho, o sal e metade do grão-de-bico e processe por 1 minuto. Acrescente o restante do grão-de-bico.","Com o processador ligado, adicione a água gelada aos poucos e o azeite, até obter uma pasta lisa e cremosa. Acerte o sal e o limão.","Transfira para um pote, regue com azeite e polvilhe a páprica. Sirva com os palitos de cenoura, pepino e pimentão."],
["A água gelada deixa o homus mais claro e leve.","Se quiser textura mais lisa, retire a pele dos grãos antes de processar.","Confira no rótulo o grão-de-bico e o tahine, que pode ser processado com outros ingredientes."],
"Até 5 dias na geladeira, em pote fechado, coberto com fio de azeite. Não congelar.","homus grão-de-bico tahine pasta petisco vegetariano aperitivo"),
RSC("grelhar em frigideira por 3 minutos de cada lado, em fogo médio-alto",48,"Espetinhos de frango com molho de iogurte","Petiscos","Espetinhos suculentos de frango marinado com limão e páprica, servidos com molho fresco de iogurte e hortelã.","12 espetinhos",25,null,null,
["600 g|peito de frango, em cubos de 3 cm","2 colheres de sopa|azeite","2 colheres de sopa|suco de limão","2 dentes|alhos amassados","2 colheres de chá|páprica doce","1 colher de chá|orégano","5 g (1 colher de chá)|sal","12 unidades|palitos de espeto, de molho em água por 30 minutos","170 g (1 pote)|iogurte natural integral","1 colher de sopa|hortelã picada","1/2 dente|alho amassado","1 colher de chá|suco de limão"],
["Misture o frango com o azeite, o limão, o alho, a páprica, o orégano e o sal. Deixe marinar por 30 minutos a 2 horas na geladeira.","Faça o molho: misture o iogurte, a hortelã, o alho e o limão. Acerte o sal e leve à geladeira.","Monte 3 a 4 cubos de frango em cada espeto.","Aqueça uma frigideira antiaderente ou grill em fogo médio-alto. Grelhe os espetinhos por 3 minutos de cada lado, até dourarem e cozinharem por inteiro.","O frango está pronto quando não tiver partes rosadas no centro. Sirva com o molho."],
["Não amontoe os espetinhos na frigideira, para dourarem em vez de cozinhar no vapor.","Deixe o frango marinar apenas na geladeira, nunca em temperatura ambiente.","Confira no rótulo a páprica, o orégano e o iogurte. Evite temperos prontos."],
"Até 2 dias na geladeira, em recipiente fechado. Reaqueça até ficar bem quente. O molho dura até 3 dias.","espetinho frango iogurte hortelã petisco frigideira churrasco"),
RSC("grelhar em frigideira ou chapa por 2 a 3 minutos de cada lado",49,"Espetinho de queijo coalho grelhado","Petiscos","Queijo coalho dourado na frigideira, com azeite e orégano. Petisco simples e rápido.","8 espetinhos",10,null,null,
["400 g|queijo coalho, em palitos de 2 cm de espessura","8 unidades|palitos de espeto","2 colheres de sopa|azeite","1 colher de chá|orégano","1 pitada|pimenta calabresa, opcional"],
["Espete 1 a 2 pedaços de queijo em cada palito.","Aqueça uma frigideira antiaderente em fogo médio. Pincele o azeite nos espetos.","Grelhe por 2 a 3 minutos de cada lado, até o queijo dourar e amolecer por dentro.","Polvilhe o orégano e a pimenta e sirva imediatamente, ainda quente."],
["Não deixe o fogo muito alto: o queijo coalho queima rápido por fora.","Para a churrasqueira, use grelha limpa e untada.","Confira no rótulo o queijo coalho."],
"Consuma na hora, quente. O queijo coalho cru dura até 7 dias na geladeira, bem embalado.","queijo coalho espetinho grelhado petisco churrasco aperitivo"),
RS(50,"Batata rústica assada com páprica","Petiscos","Batatas com casca, assadas em gomos, douradas e crocantes por fora e macias por dentro, com alecrim.","4 porções",15,40,"220 °C",
["800 g|batatas lavadas, com casca","3 colheres de sopa|azeite","2 colheres de chá|páprica doce","1/2 colher de chá|alho em pó","5 g (1 colher de chá)|sal","2 ramos|alecrim picado"],
["Preaqueça o forno a 220 °C e forre uma assadeira grande com papel-manteiga.","Corte as batatas em gomos de 2 cm de espessura e seque-as com um pano.","Misture as batatas com o azeite, a páprica, o alho em pó, o sal e o alecrim.","Disponha numa só camada, com o lado cortado para baixo, sem sobrepor.","Asse por 35 a 40 minutos, virando na metade do tempo, até dourar e ficar crocante por fora. Espete um garfo: ele deve entrar sem resistência.","Sirva imediatamente."],
["Secar bem as batatas é o que garante a crocância.","Não use assadeira muito pequena: batatas amontoadas cozinham no vapor e não dourão.","Confira no rótulo a páprica e o alho em pó."],
"Até 2 dias na geladeira, em recipiente fechado. Reaqueça no forno ou na air fryer para recuperar a crocância.","batata rústica assada páprica alecrim petisco acompanhamento forno"),
];
